import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit

base = 'https://www.halifax.ca/business/doing-business-halifax/procurement'
source = Path('products/services/halifax-offline-rfq/raw/procurement.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '339259f746bee17cbd92a9edd149b8845db2b5a043532b019b201e003709d106', digest

class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.href = None
        self.parts = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.parts = []

    def handle_data(self, data):
        if self.href:
            self.parts.append(data)

    def handle_endtag(self, tag):
        if tag != 'a' or not self.href:
            return
        label = ' '.join(''.join(self.parts).split())
        url = urljoin(base, self.href)
        self.href = None
        if urlsplit(url).scheme in ('http', 'https') and re.search(r'biddingo|bidsandtenders|bid opportunit|tender|solicitation|request for quotation|supplier portal', label + ' ' + url, re.I):
            row = {'label': label, 'url': url}
            if row not in self.rows:
                self.rows.append(row)

parser = Links()
parser.feed(raw.decode('utf-8'))
result = {'source_url': base, 'source_sha256': digest, 'candidate_links': parser.rows, 'scope': 'Links extracted from the saved municipality page. Read adjacent text and the original notice before treating any link as a current purchasing invitation.'}
output = source.parent.parent / 'director-procurement-route.json'
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == result
print(json.dumps(result, ensure_ascii=False))
